css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .cup { position: absolute; bottom: 8%; left: 20%; width: 50%; height: 34%; background: linear-gradient(var(--accent), var(--accent-2)); border-radius: 6px 6px 42% 42%; }
.loader .cup::after { content: ''; position: absolute; top: 14%; left: 92%; width: 30%; height: 52%; border: calc(var(--loader-size) * .045) solid var(--accent-2); border-left: 0; border-radius: 0 60% 60% 0; }
.loader::after { content: ''; position: absolute; bottom: 2%; left: 12%; width: 68%; height: 5%; border-radius: 999px; background: var(--accent-2); }
.loader span { position: absolute; bottom: 44%; width: 7%; height: 28%; border-radius: 999px; background: linear-gradient(transparent, color-mix(in srgb, #fff 62%, var(--accent-2))); animation: steam calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader span:nth-child(1) { left: 26%; animation-delay: 0s; }
.loader span:nth-child(2) { left: 41%; animation-delay: calc(var(--loader-speed) * .55); }
.loader span:nth-child(3) { left: 56%; animation-delay: calc(var(--loader-speed) * 1.1); }
@keyframes steam { 0% { opacity: 0; transform: translateY(24%) scaleY(.5); } 35% { opacity: .9; } 100% { opacity: 0; transform: translateY(-86%) scaleY(1.25); } }
